  enunciado:"Assinale a alternativa que apresenta a correta correlação entre líquido pleural e provável etiologia.",
  alternativas:[{id:"A",texto:"glicose 50 mg/dL, pH 7,3 e empiema."},{id:"B",texto:"glicose 50 mg/dL, DHL 1200 U/L e quilotórax."},{id:"C",texto:"proteína 4,0 g/dL, pH 7,2 e síndrome nefrótica."},{id:"D",texto:"proteína 4,5 g/dL, ADA 43 U/L e tuberculose."}],
  gabarito:"D",
