  areaId:"area-cg", especialidadeId:"esp-perioperatorio", assuntoId:"ass-cuidadosperi",
  enunciado:"Dentre as estratégias para redução do uso de hemocomponentes no intraoperatório temos:",
  alternativas:[{id:"A",texto:"hipotermia."},{id:"B",texto:"doação heteróloga."},{id:"C",texto:"hemoconcentração normovolêmica."},{id:"D",texto:"uso do Cell Saver."}],
